{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "Removable orthoses have proven their value in the recovery process of other fractures of the long bones, and are increasingly suggested as an alternative to a cast for stable type B fractures [16, 17]. Orthoses can be taken off, allowing early (weight-bearing) mobilization, potentially preventing the consequences of rigid immobilization and accelerating recovery [16, 18].",
      "reason": "The manuscript describes the current state of knowledge about removable orthoses (evidence from other fractures and rationale for use) and mentions implications for recovery, indicating awareness of existing knowledge and uncertainties."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_16",
      "quote": "This literature review could contribute to the decrease in secondary healthcare utilization, healthcare costs and societal costs related to these injuries. ... Current literature describes promising results in terms of complications and functional outcome for a removable orthosis compared to a cast as NOM for stable type B ankle fractures. After stability assessment, using a removable orthosis for patients with a stable type B ankle fracture is advisable.",
      "reason": "The authors explain the importance and potential impact of the review (clinical implications, cost and resource implications, and practical recommendations), supporting the need for conducting the review."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PARTIAL",
      "chunk_id": "text_14",
      "quote": "This review found fewer complications in the orthosis group compared to the cast group and similarly high scores of functional outcome in both NOM-groups, partly in keeping with previous literature. Several other studies, which were not included in this review, described complications after management with a removable orthosis or cast after an ankle fracture. These studies had several important differences in study design [34-37].",
      "reason": "The manuscript compares its findings with previous studies and notes differences in design and results, but does not clearly identify or cite existing systematic reviews nor explicitly state the need for this review as an update or replication of prior systematic reviews."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "Orthoses can be taken off, allowing early (weight-bearing) mobilization, potentially preventing the consequences of rigid immobilization and accelerating recovery [16, 18].",
      "reason": "The authors briefly describe the proposed mechanism of action for removable orthoses (allowing early weight-bearing, reducing consequences of rigid immobilization) which explains how the intervention may affect outcomes."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence or figure presenting a logic model or hypothesised relationships between intervention components and outcomes is provided in the retrieved material."
    }
  ],
  "confidence": 80
}

